import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert and hostname, and return the greeting line."""
    if server_hostname is None:
        server_hostname = host
    with socket.create_connection((host, port)) as sock:
        with wrap_client_socket(sock, server_hostname, cafile) as tls_sock:
            # Read up to 4096 bytes or until first newline
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    # Connection closed
                    break
                data.extend(chunk)
                if b"\n" in chunk:
                    # Stop reading after first newline
                    break
            # Return bytes up to and including first newline, or all if no newline
            newline_pos = data.find(b"\n")
            if newline_pos != -1:
                return bytes(data[:newline_pos + 1])
            else:
                return bytes(data)
